{
  "interpretation": {
    "name": "Line2NutrunnerTighteningAndReturn",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Bring nutrunner NR7 from the crib to station st2, tighten the F30 fasteners on line 2, evaluate and record the result, then return the tool to the crib and release it.",
    "constraints": [
      "NR7 must be reserved before any tool-using Step and released after it is back in the crib",
      "transport-tool Steps must be delegated to the Executor agvexecutor",
      "transport-tool to the station must be completed before configure-tool and tighten-fasteners",
      "the tightening program must come only from get-program, with no numeric process values in the Recipe",
      "the tightening must be evaluated and recorded",
      "every tool-using Step must depend on reserve-tool so the lease is renewed, and each must be shorter than the 120 s lease"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "single execution, now",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-nutrunner-tightening",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "Deliver",
        "steps": [
          {"name": "reserve-nr7", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "get-f30-program", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "Deliver",
        "next": "Tighten",
        "steps": [
          {"name": "transport-to-station", "service": "transport-tool", "next": [], "dep": ["reserve-nr7"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "Tighten",
        "next": "Quality",
        "steps": [
          {"name": "configure-nr7", "service": "configure-tool", "next": ["tighten-nr7"], "dep": ["get-f30-program", "reserve-nr7"], "executor": null, "params": {}},
          {"name": "tighten-nr7", "service": "tighten-fasteners", "next": [], "dep": ["configure-nr7", "reserve-nr7"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "Quality",
        "next": "Return",
        "steps": [
          {"name": "evaluate-tightening-step", "service": "evaluate-tightening", "next": [], "dep": ["tighten-nr7", "get-f30-program"], "executor": null, "params": {}},
          {"name": "record-tightening-step", "service": "record-tightening", "next": [], "dep": ["tighten-nr7"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "Return",
        "next": null,
        "steps": [
          {"name": "transport-to-crib", "service": "transport-tool", "next": ["release-nr7"], "dep": ["reserve-nr7"], "executor": "agvexecutor", "params": {"to": "crib"}},
          {"name": "release-nr7", "service": "release-tool", "next": [], "dep": ["reserve-nr7"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
